import { cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { gapClassNames, type AllowedGap, type Responsive } from "@sb-components/frames/_spacing"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { principleAttr, explainAttr, type PrincipleToken, type ExplainReason } from "@sb-components/frames/_principles"
import { resolvePrincipleSpacing, resolvedSpacingClassNames } from "@sb-components/frames/_principle-style"
import { resolveIdentity, type CallerIdentity } from "@sb-components/frames/_identity"

/**
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 * LAYOUT (frame) -- `Grid.*`: the responsive grid of equal cells. One member,
 * `Grid` (a grid has one shape; density is a PROP, ┬º6b).
 *
 * FRAME API LAW (┬º13b) -- REPEATING LIST ΓçÆ `items` DATA, `children` FORBIDDEN.
 * A grid's premise is that every cell is the same kind of thing; children would
 * let one cell be something else and quietly break the premise.
 *
 * CONTAINER QUERIES, NOT VIEWPORT (`@app-*`, `globals.css`): the app shell is a
 * split -- the whole app renders in a left column that a docked AI rail can narrow
 * at will. A grid that read `md:` would keep 3 columns while its own column had
 * been squeezed to 400px. `@app-sm/md/lg` are pinned to the SAME pixel values as
 * the viewport scale, so the steps read the same but measure the CONTAINER.
 * (Tailwind's built-in `@sm/@md/@lg` are a DIFFERENT, half-size scale -- using
 * them here would silently halve every breakpoint.) These variants resolve
 * against the nearest `@container` ancestor, which the app shell (and the
 * Storybook preview) already provides -- this frame deliberately does NOT open its
 * own container, or every grid would answer to its own width instead of the shell's.
 *
 * `gap` is a {@link Responsive}<{@link AllowedGap}> ΓÇö REQUIRED when there is no
 * `principle`. When `principle` is set, the resolver owns the gap seam and the
 * public `gap` / `classNames` props are not forwarded (strict principle-only).
 * ┬º13: no domain content, no behaviour -- placement only.
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 */

/** One cell of a {@link Grid}. */
export interface GridItem {
    /** Stable React key. */
    key: string
    /**
     * The cell's content -- a card, a tile, a stat. Received UNCALLED (a component
     * reference, never a built element) so the frame can render it with `isSkeleton`.
     */
    content: ComponentTypeWithSkeleton
    /**
     * Columns this cell spans. Default `1` (no class set -- the cell stays a
     * normal one-column track). Capped at `2`: an app-wide scan found only 7
     * `col-span` call sites (5├ù`col-span-2`, 2├ù`col-span-1`), so the union stops
     * there on purpose -- a wider span or an arbitrary start position belongs to
     * a real composition decision, not a frame prop (decided by the mentor: no
     * `Col` escape hatch, that is what let `col-start-2` break mobile in `GroupPressableCard`).
     */
    span?: 1 | 2
}

/**
 * Column count per CONTAINER step. Every step is OPTIONAL and INHERITS the last
 * one set below it, so `{ base: 1, md: 2 }` means 1 column until the `@app-md`
 * step and 2 from there up. Counts are capped per step on purpose: 4 columns
 * inside a narrow shell would be unreadable, so the type refuses it.
 */
export interface GridColumns {
    /** Columns at the narrowest. Default `1`. */
    base?: 1 | 2
    /** From the `@app-sm` container step (40rem / 640px). */
    sm?: 1 | 2 | 3
    /** From the `@app-md` container step (48rem / 768px). */
    md?: 1 | 2 | 3 | 4
    /** From the `@app-lg` container step (64rem / 1024px). */
    lg?: 1 | 2 | 3 | 4
}

// Tailwind never emits an interpolated `@app-md:grid-cols-${n}` -- every supported
// count is written out so the class actually ships in the compiled CSS.
/** Base (narrowest) column count ΓåÆ literal class. */
const BASE_COLUMNS_CLASS: Record<1 | 2, string> = {
    1: "grid-cols-1",
    2: "grid-cols-2"}
/** `@app-sm` step ΓåÆ literal class. */
const SM_COLUMNS_CLASS: Record<1 | 2 | 3, string> = {
    1: "@app-sm:grid-cols-1",
    2: "@app-sm:grid-cols-2",
    3: "@app-sm:grid-cols-3"}
/** `@app-md` step ΓåÆ literal class. */
const MD_COLUMNS_CLASS: Record<1 | 2 | 3 | 4, string> = {
    1: "@app-md:grid-cols-1",
    2: "@app-md:grid-cols-2",
    3: "@app-md:grid-cols-3",
    4: "@app-md:grid-cols-4"}
/** `@app-lg` step ΓåÆ literal class. */
const LG_COLUMNS_CLASS: Record<1 | 2 | 3 | 4, string> = {
    1: "@app-lg:grid-cols-1",
    2: "@app-lg:grid-cols-2",
    3: "@app-lg:grid-cols-3",
    4: "@app-lg:grid-cols-4"}
// Same reason as the column tables above: Tailwind never emits an interpolated
// `col-span-${n}`, so the one supported span (2 -- see `GridItem.span`) is
// written out literal.
/** {@link GridItem.span} `2` ΓåÆ literal class. */
const SPAN_CLASS: Record<2, string> = {
    2: "col-span-2"}

/** Props for {@link Grid}. */
export interface GridBaseProps {
    /**
     * The cells, in reading order. REQUIRED -- repeat list = DATA, never children
     * (┬º13b). An empty array renders an empty track; the empty MESSAGE is the
     * caller's to phrase, not the frame's.
     */
    items: ReadonlyArray<GridItem>
    /**
     * Column count per container step -- REQUIRED, so the reflow is always a
     * decision. Steps are emitted in ascending width order (later wins).
     */
    columns: GridColumns
    /**
     * Seam between cells on the house gap scale. Both axes.
     * Optional when `principle` owns spacing ΓÇö the resolver supplies the gap class.
     * Still required when there is no principle.
     */
    gap?: Responsive<AllowedGap>
    /**
     * Where this sits inside its parent. Appearance is not passable -- it is already a prop.
     * Ignored when `principle` is set (strict principle-only contract).
     */
    classNames?: Array<AllowedClassName>
    /**
     * The layout pattern this frame's seam realises - one token from `test-runner/patterns.mjs`
     * (`flex-action`, `label-field`, `group-boundary`, ...). Emitted as `data-principle` on the element
     * that carries the gap, so the rendered-tree test can assert the seam is the step the pattern names.
     * Query as `[data-principle="token"]`. When set, owns gap CSS ΓÇö do not also pass `gap`/`classNames`.
     */
    principle?: PrincipleToken
    /**
     * Why this layer exists - one sentence, emitted as `data-explain` beside the token.
     * A reason, never a restatement of `principle`.
     */
    explain?: ExplainReason
    /** Renders every cell's skeleton form instead of its content form. */
    isSkeleton?: boolean
    /**
     * Caller identity to wear on this grid's root instead of the frame's own -- pass this when a
     * `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its own) is
     * using this grid AS its root element, instead of wrapping it in a raw `<div data-tier=...
     * data-component=...>`. See `_identity.ts`. Omitted ΓåÆ this grid keeps emitting its own
     * `data-tier="frame" data-component="Grid"`, unchanged.
     */
    identity?: CallerIdentity
}

/**
 * The responsive grid. See the file header for why the steps are container
 * queries and not viewport breakpoints.
 *
 * @param props - {@link GridBaseProps}
 */
const GridBase = ({ items, columns, gap, classNames, principle, explain, isSkeleton, identity }: GridBaseProps) => {
    const resolved = resolvePrincipleSpacing(principle, gap, undefined)
    const gapClasses = resolved.principleOwnsLayout
        ? resolvedSpacingClassNames(resolved)
        : gap != null
            ? gapClassNames(gap)
            : []
    return (
        <div
            {...resolveIdentity(identity, { tier: "frame", name: "Grid" })}
            data-principle={principleAttr(principle)}
            data-explain={explainAttr(explain)}
            className={cn(
                "grid",
                ...gapClasses,
                BASE_COLUMNS_CLASS[columns.base ?? 1],
                // Ascending order: a later (wider) step must be able to win.
                columns.sm != null && SM_COLUMNS_CLASS[columns.sm],
                columns.md != null && MD_COLUMNS_CLASS[columns.md],
                columns.lg != null && LG_COLUMNS_CLASS[columns.lg],
                // Strict: principle owns layout CSS ΓÇö do not forward caller classNames.
                !resolved.principleOwnsLayout && classNames)}
        >
            {items.map((item) => {
                const Content = item.content
                const spanClass = item.span === 2 ? SPAN_CLASS[2] : undefined
                // A spanning cell needs a real wrapper to hang `col-span-2` on, even
                // when `` is off -- a `Fragment` cannot carry a class. A
                // plain (non-spanning) cell keeps the old behaviour untouched.
                //
                // 2026-07-28: this wrapper used to ALSO grow under `` alone (not
                // just `spanClass`) so it could carry ``. Dropped: "Cell"
                // had no component or story of its own -- it is just this `min-w-0`/`col-span`
                // box, the frame's own geometry (┬º13z's logic one tier up), not a separate part
                // a reader could click through to. No story ever declared it, so the badge only
                // ever rendered into the DOM invisibly -- a name with nowhere to send the reader
                // is worse than no name, so the wrapper now only grows for the reason it
                // actually needs to: hanging `col-span-2` on a spanning cell.
                if (spanClass) {
                    return (
                        // `min-w-0` keeps a long-text cell from blowing out its track
                        // (grid items default to `min-width:auto`).
                        <div key={item.key} className={cn("min-w-0", spanClass)}>
                            <Content isSkeleton={isSkeleton} />
                        </div>
                    )
                }
                return <Content key={item.key} isSkeleton={isSkeleton} />
            })}
        </div>
    )
}

/**
 * `Grid.*` -- the responsive grid frame namespace. Namespace only -- no bare
 * component export (┬º13a).
 */
export { GridBase as Grid }

/** Source-level tier marker -- lets a gate read the tier without guessing from the folder path. */
export const meta = { tier: "frame", name: "Grid" } as const

import { cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { GAP_CLASS, JUSTIFY_CLASS, type AllowedGap, type LayoutJustify } from "@sb-components/frames/_spacing"
import type { ResponsiveRowSwitch } from "@sb-components/frames/ResponsiveRow/ResponsiveRow"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { principleAttr, explainAttr, type PrincipleToken, type ExplainReason } from "@sb-components/frames/_principles"

/**
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 * FRAME -- `ResponsiveCluster`: a repeat-list track that is a FULL-WIDTH COLUMN
 * below a named container step and a packed ROW from it up, ONE shared gap on
 * both sides. One member, `ResponsiveCluster`.
 *
 * See the blueprint (`.storybook/components/frames/ResponsiveCluster/ResponsiveCluster.tsx`)
 * for why this exists and why it stays internal-only for now.
 *
 * FRAME API LAW ΓçÆ REPEATING LIST ΓçÆ `items` DATA, `children` FORBIDDEN, same
 * contract as `Cluster`/`Grid`: every cell is the same kind of thing.
 *
 * FULL WIDTH BELOW THE SWITCH: each item is wrapped in `w-full`, released to
 * `w-auto` at the switch step -- the wrapper carries the class, not the item's
 * own content, so a caller's `Button` never has to know which form it is in.
 *
 * CONTAINER QUERIES, NOT VIEWPORT: same reasoning as `Grid`/`ResponsiveRow` --
 * `@app-sm/md/lg/xl` answer the nearest `@container`, not the viewport.
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 */

/** One cell of a {@link ResponsiveCluster}. */
export interface ResponsiveClusterItem {
    /** Stable React key. */
    key: string
    /**
     * The cell's content, fully built by the caller (the frame places, never styles).
     * Received UNCALLED (a component reference, never a built element) so the frame
     * can render it with `isSkeleton`.
     */
    content: ComponentTypeWithSkeleton
}

/** Props for {@link ResponsiveCluster}. */
export interface ResponsiveClusterProps {
    /** The cells, in reading order. REQUIRED -- repeat list = DATA, never children. */
    items: ReadonlyArray<ResponsiveClusterItem>
    /** Seam between cells on the house scale -- REQUIRED, ONE value, both forms. */
    gap: AllowedGap
    /** Container step the track leaves the full-width column for the packed row at. */
    at: ResponsiveRowSwitch
    /** Main-axis distribution once packed into a row. Left out means the browser default. */
    justify?: LayoutJustify
    /** Where this sits inside its parent. Appearance is not passable -- it is already a prop. */
    classNames?: Array<AllowedClassName>
    /**
     * Permanent contract marker (not anatomy tooling) -- hard-coded by whoever calls this
     * frame, because the frame has no public identity of its own yet. See the blueprint.
     */
    "data-tier"?: string
    /** Paired with `data-tier` -- the public name of the caller badging this root. */
    "data-component"?: string
    /**
     * The layout pattern this track's seam realises - one token from `test-runner/patterns.mjs`.
     * Emitted as `data-principle` on this same root, beside `data-tier`/`data-component`, so the
     * rendered-tree test can assert the seam is the step the pattern names. Query as
     * `[data-principle="token"]`. See `Flex`'s own `pattern` doc for the full contract.
     */
    principle?: PrincipleToken
    /**
     * Why this layer exists - one sentence, emitted as `data-explain` beside the token.
     * A reason, never a restatement of `principle`.
     */
    explain?: ExplainReason
    /** Renders every cell's skeleton form instead of its content form. */
    isSkeleton?: boolean
}

/** Switch step ΓåÆ the class that flips the track from a column to a row from that step up. */
const DIRECTION_SWITCH_CLASS: Record<ResponsiveRowSwitch, string> = {
    sm: "@app-sm:flex-row",
    md: "@app-md:flex-row",
    lg: "@app-lg:flex-row",
    xl: "@app-xl:flex-row",
}

/** Switch step ΓåÆ the class releasing an item from full width back to its own width. */
const ITEM_WIDTH_SWITCH_CLASS: Record<ResponsiveRowSwitch, string> = {
    sm: "@app-sm:w-auto",
    md: "@app-md:w-auto",
    lg: "@app-lg:w-auto",
    xl: "@app-xl:w-auto",
}

/**
 * The full-width-column/packed-row track. See the blueprint file header for why it
 * exists and what it deliberately does not cover.
 *
 * @param props - {@link ResponsiveClusterProps}
 */
const ResponsiveClusterBase = ({
    items,
    gap,
    at,
    justify,
    classNames,
    "data-tier": dataTier,
    "data-component": dataComponent,
    principle,
    explain,
    isSkeleton,
}: ResponsiveClusterProps) => (
    <div
        data-tier={dataTier}
        data-component={dataComponent}
        data-principle={principleAttr(principle)}
        data-explain={explainAttr(explain)}
        className={cn(
            "flex w-full flex-col items-center",
            GAP_CLASS[gap],
            DIRECTION_SWITCH_CLASS[at],
            justify != null && JUSTIFY_CLASS[justify],
            classNames,
        )}
    >
        {items.map((item) => {
            const Content = item.content
            return (
                <div key={item.key} className={cn("w-full", ITEM_WIDTH_SWITCH_CLASS[at])}>
                    <Content isSkeleton={isSkeleton} />
                </div>
            )
        })}
    </div>
)

/**
 * `ResponsiveCluster.*` -- namespace only, no bare component export (house convention
 * for every frame in this folder).
 */
export { ResponsiveClusterBase as ResponsiveCluster }

import React from "react"
import type { ReactNode } from "react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { type AllowedGap, type LayoutAlign, type LayoutJustify, type PaddingValue, type Responsive } from "@sb-components/frames/_spacing"
import { Flex } from "@sb-components/frames/Flex/Flex"
import type { ResponsiveRowSwitch } from "@sb-components/frames/ResponsiveRow/ResponsiveRow"
import type { PrincipleToken, ExplainReason } from "@sb-components/frames/_principles"
import type { CallerIdentity } from "@sb-components/frames/_identity"

/**
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 * LAYOUT (frame) -- `Stack.*`: the base one-axis track. Two members = two AXES,
 * the only real shapes a stack has:
 *   ΓÇó `StackV` -- stacks VERTICALLY (column).
 *   ΓÇó `StackH` -- stacks HORIZONTALLY (row); only this axis takes `at` (FRAME-10:
 *     the container step it wraps below, never a bare boolean).
 *
 * FRAME API LAW (┬º13b): a stack WRAPS arbitrary content -- it is not a repeating
 * list -- so `children` is the road (there is no `header`/`body`/`footer` trio to
 * name: a track has exactly ONE slot, its content). `items` would be wrong here;
 * see `Cluster`/`Grid` for the repeat-list frames of this folder.
 *
 * WHY THIS FRAME EXISTS: `gap` is typed {@link Responsive}<{@link AllowedGap}> -- a
 * CLOSED index into the house gap table. Off-scale (`gap-4.5`, `gap-[13px]`) cannot even
 * be typed, so the scale is enforced by the COMPILER instead of by review.
 * `gap` is REQUIRED for the same reason: an implicit default would let the seam
 * be chosen by accident, and ┬º10a says a seam has exactly one deliberate owner.
 *
 * ┬º13 boundaries respected: no domain content, no feature behaviour -- the track
 * only decides direction / gap / alignment / an optional rule between children.
 * `divider` COMPOSES the existing `Divider` atom (┬º13c: a frame never
 * hand-rolls what an atom already owns).
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 */

/** Props shared by both axes of {@link Stack}. */
export interface StackBaseProps {
    /**
     * Seam between children on the house gap scale.
     * Optional when `principle` is a gap-owning token ΓÇö the principle resolves the class.
     * Still required when there is no gap principle (Flex enforces at render via ownership).
     */
    gap?: Responsive<AllowedGap>
    /** Cross-axis alignment (`V` ΓåÆ horizontal, `H` ΓåÆ vertical). */
    align?: LayoutAlign
    /** Main-axis distribution (`V` ΓåÆ vertical, `H` ΓåÆ horizontal). */
    justify?: LayoutJustify
    /** `true` ΓåÆ inserts `Divider` BETWEEN children (never before the first / after the last). */
    divider?: boolean
    /**
     * Space INSIDE the track, same scale as `gap`.
