                direction="col"
                principle={principle}
                explain={explain}
                identity={identity}
                body={divider ? interleaveDividers(content, "vertical") : content}
            />
        )
    }
    return (
        <Flex
            as={Tag}
            inline={inline}
            direction="col"
            gap={gap}
            padding={padding}
            align={align}
            justify={justify}
            nested={nested}
            classNames={classNames}
            identity={identity}
            body={divider ? interleaveDividers(content, "vertical") : content}
        />
    )
