     * The cell's content, fully built by the caller (the frame places, never styles).
     * Received UNCALLED (a component reference, never a built element) so the frame
     * can render it with `isSkeleton`.
     */
    content: ComponentTypeWithSkeleton
}

/** Props for {@link ResponsiveCluster}. */
export interface ResponsiveClusterProps {
    /** The cells, in reading order. REQUIRED -- repeat list = DATA, never children. */
    items: ReadonlyArray<ResponsiveClusterItem>
    /** Seam between cells on the house scale -- REQUIRED, ONE value, both forms. */
    gap: AllowedGap
    /** Container step the track leaves the full-width column for the packed row at. */
    at: ResponsiveRowSwitch
    /** Main-axis distribution once packed into a row. Left out means the browser default. */
    justify?: LayoutJustify
    /** Where this sits inside its parent. Appearance is not passable -- it is already a prop. */
    classNames?: Array<AllowedClassName>
    /**
     * Permanent contract marker (not anatomy tooling) -- hard-coded by whoever calls this
     * frame, because the frame has no public identity of its own yet. See the blueprint.
     */
    "data-tier"?: string
    /** Paired with `data-tier` -- the public name of the caller badging this root. */
    "data-component"?: string
    /**
     * The layout pattern this track's seam realises - one token from `test-runner/patterns.mjs`.
     * Emitted as `data-principle` on this same root, beside `data-tier`/`data-component`, so the
     * rendered-tree test can assert the seam is the step the pattern names. Query as
     * `[data-principle="token"]`. See `Flex`'s own `pattern` doc for the full contract.
     */
    principle?: PrincipleToken
    /**
     * Why this layer exists - one sentence, emitted as `data-explain` beside the token.
     * A reason, never a restatement of `principle`.
     */
    explain?: ExplainReason
    /** Renders every cell's skeleton form instead of its content form. */
    isSkeleton?: boolean
}

/** Switch step ΓåÆ the class that flips the track from a column to a row from that step up. */
const DIRECTION_SWITCH_CLASS: Record<ResponsiveRowSwitch, string> = {
    sm: "@app-sm:flex-row",
    md: "@app-md:flex-row",
    lg: "@app-lg:flex-row",
    xl: "@app-xl:flex-row",
}

/** Switch step ΓåÆ the class releasing an item from full width back to its own width. */
const ITEM_WIDTH_SWITCH_CLASS: Record<ResponsiveRowSwitch, string> = {
    sm: "@app-sm:w-auto",
    md: "@app-md:w-auto",
    lg: "@app-lg:w-auto",
    xl: "@app-xl:w-auto",
}

/**
 * The full-width-column/packed-row track. See the blueprint file header for why it
 * exists and what it deliberately does not cover.
 *
 * @param props - {@link ResponsiveClusterProps}
 */
const ResponsiveClusterBase = ({
    items,
    gap,
    at,
    justify,
    classNames,
    "data-tier": dataTier,
    "data-component": dataComponent,
    principle,
    explain,
    isSkeleton,
}: ResponsiveClusterProps) => (
    <div
        data-tier={dataTier}
        data-component={dataComponent}
        data-principle={principleAttr(principle)}
        data-explain={explainAttr(explain)}
        className={cn(
            "flex w-full flex-col items-center",
            GAP_CLASS[gap],
            DIRECTION_SWITCH_CLASS[at],
            justify != null && JUSTIFY_CLASS[justify],
            classNames,
        )}
    >
        {items.map((item) => {
            const Content = item.content
            return (
                <div key={item.key} className={cn("w-full", ITEM_WIDTH_SWITCH_CLASS[at])}>
                    <Content isSkeleton={isSkeleton} />
                </div>
            )
        })}
    </div>
)

/**
 * `ResponsiveCluster.*` -- namespace only, no bare component export (house convention
 * for every frame in this folder).
 */
export { ResponsiveClusterBase as ResponsiveCluster }

import React from "react"
import type { ReactNode } from "react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Divider } from "@/components/atoms/display/Divider"
import { type AllowedGap, type LayoutAlign, type LayoutJustify, type PaddingValue, type Responsive } from "@/components/frames/_spacing"
import { Flex } from "@/components/frames/Flex"
import type { ResponsiveRowSwitch } from "@/components/frames/ResponsiveRow"
import type { PrincipleToken, ExplainReason } from "@/components/frames/_principles"
import type { CallerIdentity } from "@/components/frames/_identity"

/**
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 * LAYOUT (frame) -- `Stack.*`: the base one-axis track. Two members = two AXES,
 * the only real shapes a stack has:
 *   ΓÇó `StackV` -- stacks VERTICALLY (column).
 *   ΓÇó `StackH` -- stacks HORIZONTALLY (row); only this axis takes `at` (FRAME-10:
 *     the container step it wraps below, never a bare boolean).
 *
 * FRAME API LAW (┬º13b): a stack WRAPS arbitrary content -- it is not a repeating
 * list -- so `children` is the road (there is no `header`/`body`/`footer` trio to
 * name: a track has exactly ONE slot, its content). `items` would be wrong here;
 * see `Cluster`/`Grid` for the repeat-list frames of this folder.
 *
 * WHY THIS FRAME EXISTS: `gap` is typed {@link Responsive}<{@link AllowedGap}> -- a
 * CLOSED index into the house gap table. Off-scale (`gap-4.5`, `gap-[13px]`) cannot even
 * be typed, so the scale is enforced by the COMPILER instead of by review.
 * `gap` is REQUIRED for the same reason: an implicit default would let the seam
 * be chosen by accident, and ┬º10a says a seam has exactly one deliberate owner.
 *
 * ┬º13 boundaries respected: no domain content, no feature behaviour -- the track
 * only decides direction / gap / alignment / an optional rule between children.
 * `divider` COMPOSES the existing `Divider` atom (┬º13c: a frame never
 * hand-rolls what an atom already owns).
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 */

/** Props shared by both axes of {@link Stack}. */
export interface StackBaseProps {
    /**
     * Seam between children on the house gap scale.
     * Optional when `principle` is a gap-owning token ΓÇö the principle resolves the class.
     * Still required when there is no gap principle (Flex enforces at render via ownership).
     */
    gap?: Responsive<AllowedGap>
    /** Cross-axis alignment (`V` ΓåÆ horizontal, `H` ΓåÆ vertical). */
    align?: LayoutAlign
    /** Main-axis distribution (`V` ΓåÆ vertical, `H` ΓåÆ horizontal). */
    justify?: LayoutJustify
    /** `true` ΓåÆ inserts `Divider` BETWEEN children (never before the first / after the last). */
    divider?: boolean
    /**
     * Space INSIDE the track, same scale as `gap`.
     *
     * 2026-07-27: forwarded down to `Flex` so a stack that also needs padding no longer
     * has to DROP to `Flex` and lose `divider` plus the axis semantics. That drop was the
     * one remaining reason to reach past this frame, and a way out that costs less than the
     * proper road always wins -- the same force that produced 227 hand-written
     * `flex flex-col gap-4` in the first place.
     */
    padding?: Responsive<PaddingValue>
    /**
     * `true` ΓåÆ a left guide border + matching indent (`pl-3`, `@app-sm:pl-6`),
     * for a track that is ONE LEVEL DEEPER than its caller (a threaded reply,
     * a nested tree row) -- the frame owns the exact classes so no block ever
     * hand-writes `border-l`/`pl-*` itself (teacher 2026-07-28). Same vocabulary
     * as `SurfaceCard`'s own `variant="nested"` (border marks "inside a
     * parent", not a fresh outer face) -- this is that same idea for a track.
     */
    nested?: boolean
    /**
     * The HTML element to render, forwarded to `Flex`. Defaults to `div`.
     *
     * Added 2026-07-29 for the same reason `padding` was: a stack that also needed a real tag
     * (`section`, `figure`, `span`) had to DROP to hand-written classes and lose the axis
     * semantics along the way. Three call-sites sat outside the frame tier for exactly that.
     */
    as?: "div" | "section" | "figure" | "span" | "li"
    /**
     * `true` ΓåÆ the track hugs its content (`inline-flex`) instead of taking the whole line.
     * Measured on the same content: the block box came out 503px, the inline box 136px.
     */
    inline?: boolean
    /**
     * Anatomy tag for THIS frame itself -- so the PARENT can badge it as ONE node (┬º11a.1).
     * Missing this prop means the `layouts`-tier frame is used but the panel cannot see it.
     */
    /** A SINGLE buildable child -- an uncalled `ComponentType<{isSkeleton?}>` the track renders itself. Use `items` for several. */
    body?: ComponentTypeWithSkeleton
    /**
     * The stacked content as BUILDABLE items -- each an uncalled `ComponentType<{isSkeleton?}>`
     * the track renders itself, so it can thread `isSkeleton` down and interleave dividers. Preferred
     * over `body`: a frame that can BUILD its children can shimmer them (one tree, no hand-mirror).
     * Wins over `body` when both are passed.
     */
    items?: Array<ComponentTypeWithSkeleton>
    /** `true` ΓåÆ the track passes `isSkeleton` to every `items` component so the whole column shimmers. */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable -- it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * The layout pattern this track's seam realises - forwarded straight to the `Flex` this
     * track renders through, the same way `gap`/`align`/`justify` are. See `Flex`'s own
     * `pattern` doc for the full contract. Query as `[data-principle="token"]`.
     */
    principle?: PrincipleToken
    /**
     * Why this layer exists - one sentence, emitted as `data-explain` beside the token.
     * A reason, never a restatement of `principle`. Forwarded to `Flex`.
     */
    explain?: ExplainReason
    /**
     * Caller identity to wear on this track's root instead of `Stack`'s own -- pass this when a
     * `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its own) is
     * using this track AS its root element, instead of wrapping it in a raw `<div data-tier=...
     * data-component=...>`. Forwarded straight to `Flex`, which is what actually renders the DOM
     * (see `Flex`'s own `identity` doc). See `_identity.ts`. Omitted ΓåÆ this track keeps
     * emitting `data-tier="frame" data-component="Flex"`, unchanged.
     */
    identity?: CallerIdentity
}

/** Props for {@link StackV} -- a vertical track (no row-only prop to add). */
export type StackVProps = StackBaseProps

/** Props for {@link StackH} -- a horizontal track. */
export interface StackHProps extends StackBaseProps {
    /**
     * Container step the row switches from wrapped to single-line at (FRAME-10). Below `at`
     * children flow onto a new line when the row runs out of width; at `at` and above the row
     * stays single-line. ROW-ONLY: a column already grows without bound, so this is meaningless
     * on `StackV` and is not offered there. Left out, the row never wraps -- same behaviour the
     * old `wrap={false}` default had.
     */
    at?: ResponsiveRowSwitch
}

/**
 * Interleaves `Divider` between children -- NOT around them: N children get
 * NΓêÆ1 rules. The atom carries its own `` (part name `Line`), so the
 * frame adds no wrapper element and the DOM is identical with badges on or off.
 *
 * On a ROW the rule is vertical and gets `self-stretch`: `align-self` overrides
 * the track's `items-*`, so the line spans the row's full height even when the
 * row is `items-center`.
 */
const interleaveDividers = (children: ReactNode, axis: "vertical" | "horizontal") => {
    const nodes = React.Children.toArray(children)
    // `axis` = the TRACK's direction; a rule always runs ACROSS it.
    const ruleOrientation = axis === "vertical" ? "horizontal" : "vertical"
    return nodes.flatMap((child, index) =>
        index === 0
            ? [child]
            : [
                <Divider
                    key={`stack-divider-${index}`}
                    orientation={ruleOrientation}
                    classNames={ruleOrientation === "vertical" ? ["self-stretch"] : undefined}
                />,
                child,
            ],
    )
}

/**
 * Vertical track -- the default way to stack anything down a column.
 *
 * @param props - {@link StackVProps}
 */
const StackV = ({
    as: Tag,
    inline,
    gap,
    align = "stretch",
    justify,
    divider = false,
    nested = false,
    body,
    items,
    isSkeleton,
    padding,
    classNames,
    principle,
    explain,
    identity}: StackVProps) => {
    // `items` (buildable) wins over legacy `body`: the track renders each item itself, threading
    // `isSkeleton`, so it can shimmer the whole column and interleave dividers on the real children.
    const content = (items ?? (body ? [body] : [])).map((Item, index) => <Item key={index} isSkeleton={isSkeleton} />)
    // Strict contract: when `principle` is set it owns the full CSS ΓÇö do not forward
    // gap/padding/align/justify/classNames/inline/nested from the caller.
    if (principle) {
        return (
            <Flex
                as={Tag}
                direction="col"
                principle={principle}
                explain={explain}
                identity={identity}
                body={divider ? interleaveDividers(content, "vertical") : content}
            />
        )
    }
    return (
        <Flex
            as={Tag}
            inline={inline}
            direction="col"
            gap={gap}
            padding={padding}
            align={align}
            justify={justify}
            nested={nested}
            classNames={classNames}
            identity={identity}
            body={divider ? interleaveDividers(content, "vertical") : content}
        />
    )
}

const StackH = ({
    as: Tag,
    inline,
    gap,
    align = "center",
    justify,
    at,
    divider = false,
    nested = false,
    body,
    items,
    isSkeleton,
    padding,
    classNames,
    principle,
    explain,
    identity}: StackHProps) => {
    const content = (items ?? (body ? [body] : [])).map((Item, index) => <Item key={index} isSkeleton={isSkeleton} />)
    if (principle) {
        return (
            <Flex
                as={Tag}
                direction="row"
                principle={principle}
                explain={explain}
                identity={identity}
                // `at` is a named width switch (FRAME-10), not a free CSS boolean ΓÇö still forwarded.
                at={at}
                body={divider ? interleaveDividers(content, "horizontal") : content}
            />
        )
    }
    return (
        <Flex
            as={Tag}
            inline={inline}
            direction="row"
            gap={gap}
            padding={padding}
            align={align}
            justify={justify}
            at={at}
            nested={nested}
            classNames={classNames}
            identity={identity}
            body={divider ? interleaveDividers(content, "horizontal") : content}
        />
    )
}

export { StackV, StackH }

/**
 * Source-level tier marker -- lets a gate read the tier without guessing from the folder path.
 *
 * Shaped as a record, not the single `{ tier, name }` most frame files export: this file has
 * TWO public components, not one, and neither is more "the" component this file names. See
 * `Flex`'s own `meta` note for the DOM side of this -- `StackV`/`StackH` render no element
 * of their own (100% delegated to `Flex`), so `data-component` on a rendered Stack instance
 * reads `"Flex"`, not `"StackV"`/`"StackH"`; this export is the source-level identity, which a
 * gate can still read even though the DOM cannot show it.
 */
export const meta = {
    StackV: { tier: "frame", name: "StackV" },
    StackH: { tier: "frame", name: "StackH" },
} as const
